from AlgorithmImports import *
from collections import deque
from decimal import Decimal


class IndependentSpyAaplStrategies(QCAlgorithm):
    SMA_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            security = self.AddEquity(ticker, Resolution.Daily)
            security.SetDataNormalizationMode(DataNormalizationMode.Adjusted)
            self.symbols[ticker] = security.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=self.SMA_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_close_count = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD,
            MovingAverageType.Wilders
        )

        self.strategy_a_ticket = None
        self.strategy_b_ticket = None

        self.SetWarmUp(self.SMA_PERIOD + 1, Resolution.Daily)

    def OnData(self, data):
        self.spy_crossed_above = False
        self.spy_crossed_below = False

        if data.Bars.ContainsKey(self.spy):
            self._update_spy_state(data.Bars[self.spy])

        if data.Bars.ContainsKey(self.aapl):
            self._update_aapl_state(data.Bars[self.aapl])

        self._clear_completed_tickets()

        if self.IsWarmingUp:
            return

        if any(not data.Bars.ContainsKey(symbol)
               for symbol in self.symbols.values()):
            return

        if not self._all_state_ready():
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        strategy_a_shares = int(self.Portfolio[self.spy].Quantity)
        strategy_b_shares = int(self.Portfolio[self.aapl].Quantity)

        # Evaluate every sell before any buy.
        if (
            strategy_a_shares > 0
            and self.strategy_a_ticket is None
            and self.spy_crossed_below
        ):
            self.strategy_a_ticket = self.MarketOrder(
                self.spy,
                -strategy_a_shares,
                tag="Strategy A: close crossed below SMA"
            )

        if (
            strategy_b_shares > 0
            and self.strategy_b_ticket is None
            and self.aapl_rsi.Current.Value > Decimal("60")
        ):
            self.strategy_b_ticket = self.MarketOrder(
                self.aapl,
                -strategy_b_shares,
                tag="Strategy B: RSI closed above 60"
            )

        if (
            strategy_a_shares == 0
            and self.strategy_a_ticket is None
            and self.spy_crossed_above
        ):
            quantity = int(self.CalculateOrderQuantity(self.spy, 0.40))
            if quantity > 0:
                self.strategy_a_ticket = self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A: close crossed above SMA"
                )

        if (
            strategy_b_shares == 0
            and self.strategy_b_ticket is None
            and self.aapl_red_streak >= 3
        ):
            cash_required = Decimal("20000")
            available_cash = self.Portfolio.Cash

            if available_cash >= cash_required:
                quantity = int(cash_required // aapl_close)
                if quantity > 0:
                    self.strategy_b_ticket = self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B: three or more consecutive red days"
                    )

    def _update_spy_state(self, bar):
        close = bar.Close
        self.spy_closes.append(close)

        if len(self.spy_closes) < self.SMA_PERIOD:
            return

        current_sma = sum(self.spy_closes, Decimal("0")) / Decimal(
            self.SMA_PERIOD
        )

        if (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
        ):
            self.spy_crossed_above = (
                self.spy_previous_close <= self.spy_previous_sma
                and close > current_sma
            )
            self.spy_crossed_below = (
                self.spy_previous_close >= self.spy_previous_sma
                and close < current_sma
            )

        self.spy_previous_close = close
        self.spy_previous_sma = current_sma

    def _update_aapl_state(self, bar):
        close = bar.Close

        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_previous_close = close
        self.aapl_close_count += 1
        self.aapl_rsi.Update(bar.EndTime, close)

    def _all_state_ready(self):
        return (
            self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.aapl_close_count >= 4
            and self.aapl_rsi.IsReady
        )

    def _clear_completed_tickets(self):
        terminal_statuses = [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

        if (
            self.strategy_a_ticket is not None
            and self.strategy_a_ticket.Status in terminal_statuses
        ):
            self.strategy_a_ticket = None

        if (
            self.strategy_b_ticket is not None
            and self.strategy_b_ticket.Status in terminal_statuses
        ):
            self.strategy_b_ticket = None

